create or replace function public.upsert_invoice_tracking(p_service_period_id uuid,p_status public.invoice_status,p_invoice_number text,p_invoice_date date,p_due_date date,p_notes text)returns uuid language plpgsql security invoker set search_path=''as $$declare period public.service_periods%rowtype;invoice_id uuid;begin if not public.has_permission('finance.manage')then raise exception'insufficient_permission'using errcode='42501';end if;select*into period from public.service_periods where id=p_service_period_id for update;if not found then raise exception'period_not_found';end if;if exists(select 1 from public.month_closes where year=period.year and month=period.month and status='closed')then raise exception'period_closed';end if;if p_status<>'waiting'and p_invoice_date is null then raise exception'invoice_date_required';end if;insert into public.invoices(service_period_id,client_id,project_id,invoice_number,invoice_date,due_date,net_amount,vat_amount,total_amount,currency,status,notes,created_by)values(period.id,period.client_id,period.project_id,nullif(trim(p_invoice_number),''),p_invoice_date,p_due_date,period.net_amount,period.vat_amount,period.gross_amount,period.currency,p_status,p_notes,auth.uid())on conflict(service_period_id)do update set invoice_number=excluded.invoice_number,invoice_date=excluded.invoice_date,due_date=excluded.due_date,status=excluded.status,notes=excluded.notes returning id into invoice_id;update public.service_periods set invoice_status=p_status,due_date=coalesce(p_due_date,due_date)where id=period.id;update public.receivables set due_date=coalesce(p_due_date,due_date)where service_period_id=period.id;return invoice_id;end$$;
grant execute on function public.upsert_invoice_tracking(uuid,public.invoice_status,text,date,date,text)to authenticated;
